import numpy as np
from scipy.spatial.transform import Rotation as R
origins=[([0,0,.333],[0,0,0]),([0,0,0],[-np.pi/2,0,0]),([0,-.316,0],[np.pi/2,0,0]),([.0825,0,0],[np.pi/2,0,0]),([-.0825,.384,0],[-np.pi/2,0,0]),([0,0,0],[np.pi/2,0,0]),([.088,0,0],[np.pi/2,0,0])]
def tf(p=(0,0,0),r=(0,0,0)):
 t=np.eye(4);t[:3,:3]=R.from_euler('xyz',r).as_matrix();t[:3,3]=p;return t
def fk(q,offset=.107):
 t=tf([0,-.4,.78],[0,0,np.pi/2])
 for v,(p,r) in zip(q,origins):t=t@tf(p,r)@tf(r=[0,0,v])
 return t@tf([0,0,offset],[0,0,-np.pi/4])
if __name__=='__main__':
 import json
 m=json.load(open('/app/output/initial/meta.json'))['proprio']['now']
 for z in [.107,.21,.207,.1034]:
  t=fk(m[:7],z);print(z,t[:3,3],R.from_matrix(t[:3,:3]).as_quat(scalar_first=True))
 print('reported',m[16:23])
