"""Camera guided controller: Thursday 6*60+4*40=520, Friday 12*40=480.
Place 4 then 0 on placemat. Only the standard robot client provides state.
Run subcommands for observed, incremental motions; all executed targets are logged.
"""
from rcb_client import Robot
import numpy as np
from pathlib import Path
import json, argparse
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
from kin import fk
OUT=Path('/app/output')
LIMITS=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])
def ik(p,q,rotation=None):
 if rotation is None:rotation=R.from_euler('xyz',[np.pi,0,-np.pi/2]).as_matrix()
 def fun(a):
  t=fk(a)
  return np.r_[10*(t[:3,3]-p),R.from_matrix(rotation@t[:3,:3].T).as_rotvec(),.015*(a-q)]
 sol=least_squares(fun,q,bounds=(LIMITS[:,0]+.001,LIMITS[:,1]-.001),max_nfev=300)
 t=fk(sol.x)
 if np.linalg.norm(t[:3,3]-p)>.003:raise RuntimeError(f'IK error {t[:3,3]} for {p}')
 return sol.x
class Control:
 def __init__(self):
  self.r=Robot();self.res=self.r.get_obs(video='none');self.update()
 def update(self):self.state=np.array(self.res.meta['proprio']['now']);self.q=self.state[:7]
 def save(self,label):
  self.res.save(OUT/label);print(json.dumps({'label':label,'meta':self.res.meta}))
 def run(self,rows,label):
  with open(OUT/'actions.jsonl','a') as f:f.write(json.dumps({'label':label,'actions':np.asarray(rows).tolist(),'dt':.1})+'\n')
  self.res=self.r.submit('joint_position',rows,dt=.1,cameras=['forward','left','right','wrist'],video='none',note=label)
  self.update();self.save(label)
 def move(self,p,finger=.04,seconds=3,label='move'):
  dest=ik(np.array(p),self.q)
  start=np.r_[self.q,self.state[14:16]];end=np.r_[dest,finger,finger]
  n=int(seconds*10);ts=np.linspace(0,1,n);blend=ts*ts*(3-2*ts)
  self.run(start[None,:]+blend[:,None]*(end-start)[None,:],label)
 def grip(self,finger,label='grip'):
  self.run(np.tile(np.r_[self.q,finger,finger],(15,1)),label)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('action',choices=['obs','move','grip','status','replay']);p.add_argument('values',nargs='*',type=float);p.add_argument('--label',default='latest');p.add_argument('--seconds',type=float,default=3);a=p.parse_args()
 if a.action=='status':print(Robot().status())
 elif a.action=='replay':
  r=Robot()
  for line in open(OUT/'actions.jsonl'):
   x=json.loads(line);res=r.submit('joint_position',x['actions'],dt=x['dt'],video='none',note=x['label'])
   if res.done:break
 else:
  c=Control()
  if a.action=='obs':c.res=c.r.get_obs(include_depth=True,video='none');c.save(a.label)
  elif a.action=='move':c.move(a.values[:3],a.values[3] if len(a.values)>3 else .04,a.seconds,a.label)
  elif a.action=='grip':c.grip(a.values[0],a.label)
